#include <stack>
#include <algorithm>

class MinStack {
private:
    std::stack<int> s;
    std::stack<int> minStack;

public:
    void push(int val) {
        s.push(val);
        if (minStack.empty() || val <= minStack.top()) {
            minStack.push(val);
        } else {
            minStack.push(minStack.top());
        }
    }

    void pop() {
        s.pop();
        minStack.pop();
    }

    int top() { return s.top(); }
    int getMin() { return minStack.top(); }
};

#include <stack>
#include <string>

bool isValid(std::string s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '{' || c == '[') {
            st.push(c);
        } else {
            if (st.empty()) return false;
            char top = st.top();
            if ((c == ')' && top == '(') || (c == '}' && top == '{') || (c == ']' && top == '[')) {
                st.pop();
            } else {
                return false;
            }
        }
    }
    return st.empty();
}

#include <vector>
#include <stack>
#include <cmath>

std::vector<int> asteroidCollision(std::vector<int>& asteroids) {
    std::vector<int> st;
    for (int ast : asteroids) {
        bool destroyed = false;
        while (!st.empty() && ast < 0 && st.back() > 0) {
            if (st.back() < -ast) {
                st.pop_back(); // Pop smaller positive asteroid moving right
                continue;
            } else if (st.back() == -ast) {
                st.pop_back(); // Both explode
            }
            destroyed = true;
            break;
        }
        if (!destroyed) {
            st.push_back(ast);
        }
    }
    return st;
}

#include <vector>
#include <stack>
#include <algorithm>

int largestRectangleArea(std::vector<int>& heights) {
    int n = heights.size();
    std::stack<int> s;
    int maxArea = 0;

    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (!s.empty() && heights[s.top()] > h) {
            int height = heights[s.top()];
            s.pop();
            int width = s.empty() ? i : i - s.top() - 1;
            maxArea = std::max(maxArea, height * width);
        }
        s.push(i);
    }
    return maxArea;
}
